#[test]
fn in_unit_and_auto_unit_round_trip() {
    for v in [1e-9, 0.5, 1.0, 1234.5, 1e7, -3e4] {
        let q = RotationalSpeed::from_base(v);
        let auto = q.auto_unit();
        assert_close(
            RotationalSpeed::new(auto.value, auto.unit).as_base(),
            v,
            F64_TOL,
        );
        for &unit in RotationalSpeedUnit::ALL {
            let shown = q.in_unit(unit);
            assert_eq!((shown.value, shown.unit), (q.convert_to(unit), unit));
        }
    }
    assert_eq!(
        RotationalSpeed::from_base(0.0).auto_unit().unit,
        RotationalSpeedUnit::RadianPerSecond
    );
}

#[test]
fn parse_every_abbreviation() {
    assert_eq!(
        "rad/s".parse::<RotationalSpeedUnit>(),
        Ok(RotationalSpeedUnit::RadianPerSecond)
    );
    assert_eq!(
        format!("2.5 {}", "rad/s").parse::<RotationalSpeed>(),
        Ok(RotationalSpeed::new(
            2.5,
            RotationalSpeedUnit::RadianPerSecond
        ))
    );
    assert_eq!(
        "nrad/s".parse::<RotationalSpeedUnit>(),
        Ok(RotationalSpeedUnit::NanoradianPerSecond)
    );
    assert_eq!(
        format!("2.5 {}", "nrad/s").parse::<RotationalSpeed>(),
        Ok(RotationalSpeed::new(
            2.5,
            RotationalSpeedUnit::NanoradianPerSecond
        ))
    );
    assert_eq!(
        "µrad/s".parse::<RotationalSpeedUnit>(),
        Ok(RotationalSpeedUnit::MicroradianPerSecond)
    );
    assert_eq!(
        format!("2.5 {}", "µrad/s").parse::<RotationalSpeed>(),
        Ok(RotationalSpeed::new(
            2.5,
            RotationalSpeedUnit::MicroradianPerSecond
        ))
    );
    assert_eq!(
        "mrad/s".parse::<RotationalSpeedUnit>(),
        Ok(RotationalSpeedUnit::MilliradianPerSecond)
    );
    assert_eq!(
        format!("2.5 {}", "mrad/s").parse::<RotationalSpeed>(),
        Ok(RotationalSpeed::new(
            2.5,
            RotationalSpeedUnit::MilliradianPerSecond
        ))
    );
    assert_eq!(
        "crad/s".parse::<RotationalSpeedUnit>(),
        Ok(RotationalSpeedUnit::CentiradianPerSecond)
    );
    assert_eq!(
        format!("2.5 {}", "crad/s").parse::<RotationalSpeed>(),
        Ok(RotationalSpeed::new(
            2.5,
            RotationalSpeedUnit::CentiradianPerSecond
        ))
    );
    assert_eq!(
        "drad/s".parse::<RotationalSpeedUnit>(),
        Ok(RotationalSpeedUnit::DeciradianPerSecond)
    );
    assert_eq!(
        format!("2.5 {}", "drad/s").parse::<RotationalSpeed>(),
        Ok(RotationalSpeed::new(
            2.5,
            RotationalSpeedUnit::DeciradianPerSecond
        ))
    );
    assert_eq!(
        "°/s".parse::<RotationalSpeedUnit>(),
        Ok(RotationalSpeedUnit::DegreePerSecond)
    );
    assert_eq!(
        format!("2.5 {}", "°/s").parse::<RotationalSpeed>(),
        Ok(RotationalSpeed::new(
            2.5,
            RotationalSpeedUnit::DegreePerSecond
        ))
    );
    assert_eq!(
        "deg/s".parse::<RotationalSpeedUnit>(),
        Ok(RotationalSpeedUnit::DegreePerSecond)
    );
    assert_eq!(
        format!("2.5 {}", "deg/s").parse::<RotationalSpeed>(),
        Ok(RotationalSpeed::new(
            2.5,
            RotationalSpeedUnit::DegreePerSecond
        ))
    );
    assert_eq!(
        "n°/s".parse::<RotationalSpeedUnit>(),
        Ok(RotationalSpeedUnit::NanodegreePerSecond)
    );
    assert_eq!(
        format!("2.5 {}", "n°/s").parse::<RotationalSpeed>(),
        Ok(RotationalSpeed::new(
            2.5,
            RotationalSpeedUnit::NanodegreePerSecond
        ))
    );
    assert_eq!(
        "µ°/s".parse::<RotationalSpeedUnit>(),
        Ok(RotationalSpeedUnit::MicrodegreePerSecond)
    );
    assert_eq!(
        format!("2.5 {}", "µ°/s").parse::<RotationalSpeed>(),
        Ok(RotationalSpeed::new(
            2.5,
            RotationalSpeedUnit::MicrodegreePerSecond
        ))
    );
    assert_eq!(
        "m°/s".parse::<RotationalSpeedUnit>(),
        Ok(RotationalSpeedUnit::MillidegreePerSecond)
    );
    assert_eq!(
        format!("2.5 {}", "m°/s").parse::<RotationalSpeed>(),
        Ok(RotationalSpeed::new(
            2.5,
            RotationalSpeedUnit::MillidegreePerSecond
        ))
    );
    assert_eq!(
        "°/min".parse::<RotationalSpeedUnit>(),
        Ok(RotationalSpeedUnit::DegreePerMinute)
    );
    assert_eq!(
        format!("2.5 {}", "°/min").parse::<RotationalSpeed>(),
        Ok(RotationalSpeed::new(
            2.5,
            RotationalSpeedUnit::DegreePerMinute
        ))
    );
    assert_eq!(
        "deg/min".parse::<RotationalSpeedUnit>(),
        Ok(RotationalSpeedUnit::DegreePerMinute)
    );
    assert_eq!(
        format!("2.5 {}", "deg/min").parse::<RotationalSpeed>(),
        Ok(RotationalSpeed::new(
            2.5,
            RotationalSpeedUnit::DegreePerMinute
        ))
    );
    assert_eq!(
        "r/s".parse::<RotationalSpeedUnit>(),
        Ok(RotationalSpeedUnit::RevolutionPerSecond)
    );
    assert_eq!(
        format!("2.5 {}", "r/s").parse::<RotationalSpeed>(),
        Ok(RotationalSpeed::new(
            2.5,
            RotationalSpeedUnit::RevolutionPerSecond
        ))
    );
    assert_eq!(
        "rpm".parse::<RotationalSpeedUnit>(),
        Ok(RotationalSpeedUnit::RevolutionPerMinute)
    );
    assert_eq!(
        format!("2.5 {}", "rpm").parse::<RotationalSpeed>(),
        Ok(RotationalSpeed::new(
            2.5,
            RotationalSpeedUnit::RevolutionPerMinute
        ))
    );
    assert_eq!(
        "r/min".parse::<RotationalSpeedUnit>(),
        Ok(RotationalSpeedUnit::RevolutionPerMinute)
    );
    assert_eq!(
        format!("2.5 {}", "r/min").parse::<RotationalSpeed>(),
        Ok(RotationalSpeed::new(
            2.5,
            RotationalSpeedUnit::RevolutionPerMinute
        ))
    );
    assert_eq!(
        "1 not-a-unit".parse::<RotationalSpeed>(),
        Err(ParseError::UnknownUnit)
    );
}

#[test]
fn arithmetic_f64() {
    let a = RotationalSpeed::from_base(6.0);
    let b = RotationalSpeed::from_base(2.0);
    assert_eq!((a + b).as_base(), 8.0);
    assert_eq!((a - b).as_base(), 4.0);
    assert_eq!((-a).as_base(), -6.0);
    assert_eq!((a * 2.0).as_base(), 12.0);
    assert_eq!((2.0 * a).as_base(), 12.0);
    assert_eq!((a / 2.0).as_base(), 3.0);
    assert_eq!(a / b, 3.0);
    let mut c = a;
    c += b;
    c -= b;
    c *= 2.0;
    c /= 4.0;
    assert_eq!(c.as_base(), 3.0);
}

#[test]
fn arithmetic_integer() {
    let a = RotationalSpeed::<i64>::from_base(7);
    let b = RotationalSpeed::<i64>::from_base(2);
    assert_eq!(a + b, RotationalSpeed::from_base(9));
    assert_eq!(a % b, RotationalSpeed::from_base(1));
    assert_eq!(a / b, 3);
    assert!(a > b);
    assert_eq!(
        [a, b].iter().sum::<RotationalSpeed<i64>>(),
        RotationalSpeed::from_base(9)
    );
}
